import React from "react"

function PaymentMethod() {
    return (
        <div className="Subscription">
            <h1>Детали оплаты</h1>
            <h3>Осталось совсем немного. Всего лишь некоторые платежные реквизиты, и вы сможете разместить свой первый заказ уже сегодня. (Первая доставка бесплатно!)</h3>
            <div className="line"></div>
            
        </div>
    )
}

export default PaymentMethod;
